from rich.segment import Segment
from rich.cells import cell_len

def _split_cells_fixed(segment, cut):
    text, style, control = segment
    _Segment = Segment
    cell_length = segment.cell_length
    if cut >= cell_length:
        return segment, _Segment("", style, control)

    from rich.cells import get_character_cell_size as cell_size

    pos = int((cut / cell_length) * (len(text))) - 1
    if pos < 0:
        pos = 0

    before = text[:pos]
    cell_pos = cell_len(before)
    if cell_pos == cut:
        return (
            _Segment(before, style, control),
            _Segment(text[pos:], style, control),
        )

    if cell_pos > cut:
        pos = 0
        before = ""
        cell_pos = 0

    while pos < len(text):
        char = text[pos]
        pos += 1
        cell_pos += cell_size(char)
        before = text[:pos]
        if cell_pos == cut:
            return (
                _Segment(before, style, control),
                _Segment(text[pos:], style, control),
            )
        if cell_pos > cut:
            return (
                _Segment(before[: pos - 1] + " ", style, control),
                _Segment(" " + text[pos:], style, control),
            )

    raise AssertionError("Will never reach here")

text_str = "こんにちは" + "a" * 100
segment = Segment(text_str, None, None)
cut = 10
res1, res2 = _split_cells_fixed(segment, cut)
print(f"Cut: {cut}")
print(f"Res1: {repr(res1.text)} (len: {len(res1.text)}, cell_len: {cell_len(res1.text)})")
print(f"Res2: {repr(res2.text)} (len: {len(res2.text)}, cell_len: {cell_len(res2.text)})")
print(f"Total cell_len: {cell_len(res1.text) + cell_len(res2.text)}")
